package com.orcamobile.app;
import android.content.Context;
import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;

/** Host tests exercise actual archive and project-policy production code, with an explicit model/JNI fake. */
public final class GeneralPreferencesTest {
    static int assertions;
    static void check(boolean value,String message){assertions++;if(!value)throw new AssertionError(message);}
    interface Action{void run()throws Exception;}
    static void rejects(Action action,String message)throws Exception{try{action.run();throw new AssertionError(message);}catch(IOException expected){assertions++;}}
    public static void main(String[] args)throws Exception{
        File root=new File(args[0]);root.mkdirs();Context context=new Context(root);
        byte[] model=new byte[2_000_123];new Random(42).nextBytes(model);File original=new File(root,"model-immutable.3mf");Files.write(original.toPath(),model);
        CurrentModelStore.current=original;CurrentModelStore.name="Original project.3mf";CurrentModelStore.plate=2;CurrentModelStore.projectMode=2;CurrentModelStore.materials="{\"colours\":[\"#112233\"],\"flush_volumes\":[123.456789]}";CurrentModelStore.transform=new ModelTransform(15,20,30,1.1,1.2,1.3,25,-18);
        GeneralBackupArchive.backup(context);File archive=new File(root,"workspace-backup/workspace.zip");check(archive.isFile(),"A real atomic backup archive is produced");
        GeneralBackupArchive.restore(context);check(Arrays.equals(model,CurrentModelStore.restoredBytes),"Recovery retains exact original bytes beyond 2MB");check(CurrentModelStore.restoredPlate==2,"Selected plate survives recovery");check(CurrentModelStore.restoredTransform.encode().equals(CurrentModelStore.transform.encode()),"Placement survives recovery without rounding");check(CurrentModelStore.restoredName.equals("Original project.3mf"),"Display name survives recovery");
        byte[] previous=Files.readAllBytes(archive.toPath());CurrentModelStore.changed=true;rejects(()->GeneralBackupArchive.backup(context),"A changing workspace must not publish an incoherent backup");check(Arrays.equals(previous,Files.readAllBytes(archive.toPath())),"Failed backup retains previous recovery archive");CurrentModelStore.changed=false;
        Map<String,byte[]> entries=readEntries(archive);entries.get("model.3mf")[17]^=1;writeEntries(archive,entries);int before=CurrentModelStore.restores;rejects(()->GeneralBackupArchive.restore(context),"Corrupted bytes must fail checksum before native restore");check(CurrentModelStore.restores==before,"Checksum failure never publishes a replacement model");
        entries=readEntriesBytes(previous);entries.put("../outside",new byte[]{1});writeEntries(archive,entries);rejects(()->GeneralBackupArchive.restore(context),"Unexpected/path-traversal archive entries are refused");check(!new File(root,"outside").exists(),"Archive paths cannot write outside private staging");
        Files.write(archive.toPath(),previous);Thread.currentThread().interrupt();rejects(()->GeneralBackupArchive.backup(context),"Interrupted backup must fail");Thread.interrupted();check(Arrays.equals(previous,Files.readAllBytes(archive.toPath())),"Interruption leaves last successful backup usable");
        check(Arrays.stream(archive.getParentFile().listFiles()).noneMatch(f->!f.getName().equals("workspace.zip")),"Failed and successful jobs leave no partial backup/restore files");
        check(CurrentModelStore.restoredMode==2,"Full-project printer mode survives backup recovery");
        JSONObject savedMaterials=new JSONObject(CurrentModelStore.restoredMaterials);check(savedMaterials.getJSONArray("colours").getString(0).equals("#112233")&&savedMaterials.getJSONArray("flush_volumes").getDouble(0)==123.456789,"Archive restores typed material colour and precise manual flush volume overlay");
        entries=readEntriesBytes(previous);JSONObject modeMeta=new JSONObject(new String(entries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));check(modeMeta.getInt("project_mode")==2,"Archive records actual project-load mode");
        modeMeta.put("project_mode",3);entries.put("workspace.json",modeMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,entries);int restoresBeforeMode=CurrentModelStore.restores;rejects(()->GeneralBackupArchive.restore(context),"Unknown project mode must fail before restoring a model");check(CurrentModelStore.restores==restoresBeforeMode,"Invalid mode never reaches model publication");
        modeMeta.remove("project_mode");modeMeta.remove("material_edits");entries.put("workspace.json",modeMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,entries);GeneralBackupArchive.restore(context);check(CurrentModelStore.restoredMode==-1,"Historical backups without a project mode retain the legacy guards");check(CurrentModelStore.restoredMaterials.equals("{}"),"Historical backups do not invent per-project material edits");
        File step=new File(root,"model-immutable.stp");byte[] stepBytes="ISO-10303-21; ORIGINAL STEP ASSEMBLY; END-ISO-10303-21;".getBytes(java.nio.charset.StandardCharsets.UTF_8);Files.write(step.toPath(),stepBytes);CurrentModelStore.current=step;CurrentModelStore.name="Original assembly.stp";CurrentModelStore.plate=-1;CurrentModelStore.projectMode=0;CurrentModelStore.materials="{}";CurrentModelStore.stepOptions=new StepImportPreferences.Options(.0123456789,.321987654,true);
        GeneralBackupArchive.backup(context);byte[] stepArchive=Files.readAllBytes(archive.toPath());GeneralBackupArchive.restore(context);check(Arrays.equals(stepBytes,CurrentModelStore.restoredBytes),"STEP backup retains original CAD bytes rather than a tessellated 3MF");check(CurrentModelStore.restoredStepOptions.same(CurrentModelStore.stepOptions),"STEP linear/angular tolerances and split flag survive recovery without rounding");check(CurrentModelStore.restoredPlate==-1&&CurrentModelStore.restoredMode==0,"STEP recovery retains derived-geometry load semantics without inventing a project plate");check(Arrays.equals(stepBytes,Files.readAllBytes(step.toPath())),"Backup and restore do not modify original STEP source");
        entries=readEntriesBytes(stepArchive);JSONObject stepMeta=new JSONObject(new String(entries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));stepMeta.remove("step_options");entries.put("workspace.json",stepMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,entries);int stepRestores=CurrentModelStore.restores;rejects(()->GeneralBackupArchive.restore(context),"STEP backup without exact import options must not silently use current preferences");check(CurrentModelStore.restores==stepRestores,"Missing STEP tolerances never publish a model");
        entries=readEntriesBytes(stepArchive);stepMeta=new JSONObject(new String(entries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));stepMeta.getJSONObject("step_options").put("angular_rad",-1);entries.put("workspace.json",stepMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,entries);rejects(()->GeneralBackupArchive.restore(context),"Malformed STEP tolerance is rejected before publication");
        int beforeInvalidScope=CurrentModelStore.restores;
        for(String extension:new String[]{".stl",".obj",".step",".stp"}){
            Map<String,byte[]> wrongScope=readEntriesBytes(previous);byte[] originalArchiveModel=wrongScope.remove("model.3mf");wrongScope.put("model"+extension,originalArchiveModel);JSONObject wrongMode=new JSONObject(new String(wrongScope.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));wrongMode.put("extension",extension).put("plate",-1).put("project_mode",2).put("material_edits",new JSONObject());wrongScope.put("workspace.json",wrongMode.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,wrongScope);rejects(()->GeneralBackupArchive.restore(context),"Full project mode cannot attach to a "+extension+" source");
        }
        check(CurrentModelStore.restores==beforeInvalidScope,"Impossible file/mode combinations never reach native model publication");
        for(int invalidMode:new int[]{-1,0}){
            Map<String,byte[]> wrongScope=readEntriesBytes(previous);JSONObject wrongMode=new JSONObject(new String(wrongScope.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));wrongMode.put("project_mode",invalidMode);wrongScope.put("workspace.json",wrongMode.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,wrongScope);rejects(()->GeneralBackupArchive.restore(context),"Material edits cannot apply to geometry-only or legacy 3MF mode "+invalidMode);
        }
        Map<String,byte[]> stepMaterialEntries=readEntriesBytes(stepArchive);JSONObject wrongStepMaterials=new JSONObject(new String(stepMaterialEntries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));wrongStepMaterials.put("material_edits",new JSONObject(CurrentModelStore.restoredMaterials).put("colours",new JSONArray().put("#FFFFFF")));stepMaterialEntries.put("workspace.json",wrongStepMaterials.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,stepMaterialEntries);rejects(()->GeneralBackupArchive.restore(context),"A STEP backup cannot smuggle a project material overlay");
        for(Object malformed:new Object[]{"not a material object",new JSONArray().put("#FFFFFF"),JSONObject.NULL}){
            Map<String,byte[]> malformedEntries=readEntriesBytes(previous);JSONObject malformedMeta=new JSONObject(new String(malformedEntries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));malformedMeta.put("material_edits",malformed);malformedEntries.put("workspace.json",malformedMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,malformedEntries);rejects(()->GeneralBackupArchive.restore(context),"Malformed material metadata cannot be silently discarded during restore");
        }
        for(Object malformedMode:new Object[]{"2",1.5,JSONObject.NULL,true}){
            Map<String,byte[]> malformedEntries=readEntriesBytes(previous);JSONObject malformedMeta=new JSONObject(new String(malformedEntries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));malformedMeta.put("project_mode",malformedMode);malformedEntries.put("workspace.json",malformedMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,malformedEntries);rejects(()->GeneralBackupArchive.restore(context),"Noninteger or wrong-type project loading mode cannot be coerced into another behavior");
        }
        check(CurrentModelStore.restores==beforeInvalidScope,"Every malformed material scope leaves the selected model untouched");
        check(Arrays.equals(stepBytes,Files.readAllBytes(step.toPath())),"Malformed backup scope never alters original source bytes");
        String[] invalidOverlays={"{\"wrong\":1}","{\"colours\":[\"#FFFFFF\"]}","{\"colours\":[\"#FFFFFF\"],\"flush_volumes\":[12],\"unknown\":1}","{\"colours\":[123],\"flush_volumes\":[12]}","{\"colours\":[\"#GGGGGG\"],\"flush_volumes\":[12]}","{\"colours\":\"#FFFFFF\",\"flush_volumes\":[12]}","{\"colours\":[\"#FFFFFF\"],\"flush_volumes\":[\"12\"]}","{\"colours\":[\"#FFFFFF\"],\"flush_volumes\":[-1]}","{\"colours\":[\"#FFFFFF\"],\"flush_volumes\":[20001]}","{\"colours\":[\"#FFFFFF\"],\"flush_volumes\":[true]}","{\"colours\":[\"#000000\",\"#FFFFFF\"],\"flush_volumes\":[0,10,0]}","{\"colours\":[],\"flush_volumes\":[]}"};
        int beforeBadOverlays=CurrentModelStore.restores;
        for(String bad:invalidOverlays){Map<String,byte[]> malformedEntries=readEntriesBytes(previous);JSONObject malformedMeta=new JSONObject(new String(malformedEntries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));malformedMeta.put("material_edits",new JSONObject(bad));malformedEntries.put("workspace.json",malformedMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,malformedEntries);rejects(()->GeneralBackupArchive.restore(context),"Malformed native material overlay must fail before model publication: "+bad);}
        check(CurrentModelStore.restores==beforeBadOverlays,"Unknown keys, invalid colours, types, bounds or matrix dimensions never replace the current model");
        Map<String,byte[]> geometryEntries=readEntriesBytes(previous);JSONObject geometryMeta=new JSONObject(new String(geometryEntries.get("workspace.json"),java.nio.charset.StandardCharsets.UTF_8));geometryMeta.put("project_mode",0).put("material_edits",new JSONObject());geometryEntries.put("workspace.json",geometryMeta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));writeEntries(archive,geometryEntries);GeneralBackupArchive.restore(context);check(CurrentModelStore.restoredMode==0&&new JSONObject(CurrentModelStore.restoredMaterials).length()==0,"Valid geometry-only 3MF recovery remains available with an empty overlay");
        GeneralProjectPolicy empty=GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"project_config\":{},\"embedded_presets\":[],\"plates\":[]}}"));check(empty.project&&!empty.settingsPresent&&!empty.customCodePresent,"Empty geometry-only 3MF is not called configured or modified G-code");check(!empty.needsDecision("ask_when_relevant")&&empty.needsDecision("always_ask"),"Always Ask and Ask When Relevant have distinct consumers");
        JSONObject configured=new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"project_config\":{\"layer_height\":\"0.24\",\"machine_start_gcode\":\"G28\"}}}");String untouched=configured.toString();GeneralProjectPolicy policy=GeneralProjectPolicy.inspect(configured);check(policy.settingsPresent&&policy.customCodePresent,"Embedded settings and custom/unverified G-code are detected");check(policy.needsDecision("load_all")&&policy.needsDecision("ask_when_relevant")&&!policy.needsDecision("load_geometry"),"Configured Load All requires explicit fallback, Geometry Only keeps its deliberate choice");check(configured.toString().equals(untouched),"Import policy never strips or rewrites project configuration");
        check(GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"plates\":[{\"config\":{\"layer_height\":\"0.18\"}}]}} ")).settingsPresent,"Plate config is included in relevant-project detection");
        check(GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"plate_custom_gcode\":[{\"items\":[{\"extra\":\"M600\"}]}]}} ")).customCodePresent,"Custom plate G-code warning is consumed");
        check(!GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"obj\",\"project_config\":{\"x\":1}} ")).needsDecision("always_ask"),"Project load preference does not prompt for ordinary OBJ");
        JSONObject objectOnly=new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"project_config\":{},\"objects\":[{\"config\":{\"layer_height\":\"0.16\"},\"volumes\":[],\"layer_height_profile\":[]}]}}");String objectOriginal=objectOnly.toString();GeneralProjectPolicy objectPolicy=GeneralProjectPolicy.inspect(objectOnly);
        check(objectPolicy.settingsPresent&&!objectPolicy.customCodePresent,"Object-only process overrides are relevant project settings without being called custom G-code");check(objectPolicy.needsDecision("ask_when_relevant")&&objectPolicy.needsDecision("load_all"),"Object-only settings cannot silently enter the geometry fallback in relevant/load-all modes");check(!objectPolicy.needsDecision("load_geometry"),"Explicit geometry-only mode remains a deliberate choice for object-scoped settings");check(objectOnly.toString().equals(objectOriginal),"Object scope inspection does not strip original options");
        JSONObject volumeOnly=new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"objects\":[{\"config\":{},\"volumes\":[{\"name\":\"outer shell\",\"config\":{\"wall_loops\":\"4\"}}]}]}}");String volumeOriginal=volumeOnly.toString();check(GeneralProjectPolicy.inspect(volumeOnly).settingsPresent&&GeneralProjectPolicy.inspect(volumeOnly).needsDecision("ask_when_relevant"),"A volume override is relevant even with no global or object config");check(volumeOnly.toString().equals(volumeOriginal),"Volume-scoped metadata stays byte-for-byte unchanged by the policy object");
        JSONObject layerOnly=new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"objects\":[{\"config\":{},\"layer_config_ranges\":[{\"z_min\":4.2,\"z_max\":6.4,\"config\":{\"sparse_infill_density\":\"85%\"}}]}]}}");String layerOriginal=layerOnly.toString();check(GeneralProjectPolicy.inspect(layerOnly).settingsPresent&&GeneralProjectPolicy.inspect(layerOnly).needsDecision("ask_when_relevant"),"Height-range-only overrides trigger the project decision through nested arrays");check(layerOnly.toString().equals(layerOriginal),"Layer range bounds and values survive policy inspection unchanged");
        JSONObject adaptiveOnly=new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"objects\":[{\"config\":{},\"layer_config_ranges\":[],\"layer_height_profile\":[0.0,0.2,3.5,0.12]}]}}");String adaptiveOriginal=adaptiveOnly.toString();check(GeneralProjectPolicy.inspect(adaptiveOnly).settingsPresent&&GeneralProjectPolicy.inspect(adaptiveOnly).needsDecision("ask_when_relevant"),"Adaptive layer-height profile alone counts as settings");check(adaptiveOnly.toString().equals(adaptiveOriginal),"Adaptive profile positions and heights are never rewritten by detection");
        JSONObject nestedEmpty=new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"project_config\":{},\"embedded_presets\":[],\"objects\":[{\"config\":{},\"layer_height_profile\":[],\"layer_config_ranges\":[{\"z_min\":0,\"z_max\":10,\"config\":{}}],\"volumes\":[{\"config\":{}}]}]}}");GeneralProjectPolicy emptyScopes=GeneralProjectPolicy.inspect(nestedEmpty);check(!emptyScopes.settingsPresent&&!emptyScopes.needsDecision("ask_when_relevant"),"Empty object/volume/layer/profile containers do not misclassify geometry as configured");check(emptyScopes.needsDecision("always_ask"),"Always Ask still prompts for an empty-scope geometry project");
        check(GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"3mf\",\"objects\":[{\"volumes\":[{\"config\":{\"wall_loops\":\"2\"}}]}]}")).settingsPresent,"Unwrapped legacy project summaries retain nested override detection");
        check(!GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"3mf\",\"source_format\":\"step\",\"project_data\":{\"objects\":[{\"config\":{\"layer_height\":\"0.2\"}}]}}")).project,"STEP-derived preview metadata cannot masquerade as an original configured 3MF import");
        GeneralProjectPolicy nestedCode=GeneralProjectPolicy.inspect(new JSONObject("{\"format\":\"3mf\",\"project_data\":{\"objects\":[{\"volumes\":[{\"config\":{\"before_layer_change_gcode\":\"G4 P100\"}}]}]}}"));check(nestedCode.settingsPresent&&nestedCode.customCodePresent,"Nested per-volume custom G-code retains both the settings decision and warning");
        System.out.println("General backup/project policy: "+assertions+" assertions passed (native/JNI boundary stub)");
    }
    static Map<String,byte[]> readEntries(File file)throws Exception{return readEntriesBytes(Files.readAllBytes(file.toPath()));}
    static Map<String,byte[]> readEntriesBytes(byte[] data)throws Exception{Map<String,byte[]> entries=new LinkedHashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(data))){ZipEntry e;while((e=zip.getNextEntry())!=null)entries.put(e.getName(),zip.readAllBytes());}return entries;}
    static void writeEntries(File file,Map<String,byte[]> entries)throws Exception{try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(file.toPath()))){for(Map.Entry<String,byte[]> e:entries.entrySet()){zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue());zip.closeEntry();}}}
}
